interface PricingPolicy {
    double priceFor(int quantity);
}

class DiscountPricingPolicy implements PricingPolicy {
    private static final double UNIT_PRICE = 10.0;

    @Override
    public double priceFor(int quantity) {
        double total = quantity * UNIT_PRICE;
        return quantity >= 10 ? total * 0.9 : total;
    }
}

import org.springframework.stereotype.Service;

@Service
class OrderService {

    private final PricingPolicy pricingPolicy;

    // Constructor injection: Spring resolve theo type trước; nếu có nhiều
    // bean cùng type thì theo tên tham số; cuối cùng theo index để phân biệt.
    OrderService(PricingPolicy pricingPolicy) {
        this.pricingPolicy = pricingPolicy;
    }

    double quote(int quantity) {
        return pricingPolicy.priceFor(quantity);
    }
}

import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.stereotype.Service;

interface NotificationSender { void send(String to, String body); }

@Service("emailSender")
class EmailSender implements NotificationSender {
    @Override public void send(String to, String body) { }
}

@Service("smsSender")
class SmsSender implements NotificationSender {
    @Override public void send(String to, String body) { }
}

@Service
class OrderNotifier {
    private final NotificationSender sender;   // final -> bat bien, thread-safe

    // mot constructor duy nhat: khong can @Autowired tu Spring 4.3
    // nhieu bean cung type -> phai chi dinh bang @Qualifier
    OrderNotifier(@Qualifier("emailSender") NotificationSender sender) {
        this.sender = sender;
    }

    void notifyPaid(String customer) {
        sender.send(customer, "Order paid");
    }
}

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean;

// gom property co lien quan vao mot POJO co kieu, validate duoc
@ConfigurationProperties(prefix = "payment")
record PaymentProperties(String apiUrl, int timeoutMs) {}

class PaymentClient {
    private final PaymentProperties props;
    PaymentClient(PaymentProperties props) { this.props = props; }
    String endpoint() { return props.apiUrl(); }
}

@Configuration
class PaymentConfig {

    // tham so cua @Bean duoc container resolve giong tham so constructor
    @Bean
    @ConditionalOnMissingBean          // lui lai neu ung dung da tu dinh nghia bean nay
    PaymentClient paymentClient(PaymentProperties props) {
        return new PaymentClient(props);
    }
}

